const __pageData = JSON.parse('{"title":"JD Vance","description":"","frontmatter":{"title":"JD Vance","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["republican","vice-president","2024-election"],"sources":["raw/a-week-to-remember.md","raw/are-we-being-distracted.md","raw/badlands-brief-029.md","raw/badlands-brief-05f.md","raw/badlands-brief-094.md","raw/badlands-brief-165.md","raw/badlands-brief-4ec.md","raw/badlands-brief-6b4.md","raw/badlands-brief-739.md","raw/badlands-brief-708.md","raw/badlands-brief-861.md","raw/badlands-brief-8c2.md","raw/badlands-brief-9ac.md","raw/badlands-brief-a6b.md","raw/badlands-brief-abf.md","raw/badlands-brief-a84.md","raw/badlands-brief-c07.md","raw/badlands-news-brief-071.md","raw/badlands-news-brief-0ad.md","raw/badlands-news-brief-189.md","raw/badlands-news-brief-1ed.md","raw/badlands-news-brief-201.md","raw/badlands-news-brief-3a5.md","raw/badlands-news-brief-467.md","raw/badlands-news-brief-4fd.md","raw/badlands-news-brief-50f.md","raw/badlands-news-brief-582.md","raw/badlands-news-brief-60c.md","raw/badlands-news-brief-6aa.md","raw/badlands-news-brief-69b.md","raw/badlands-news-brief-6e5.md","raw/badlands-news-brief-6e6.md","raw/badlands-news-brief-74a.md","raw/badlands-news-brief-752.md","raw/badlands-news-brief-786.md","raw/badlands-news-brief-795.md","raw/badlands-news-brief-7bf.md","raw/badlands-news-brief-7bb.md","raw/badlands-news-brief-7b8.md","raw/badlands-news-brief-8ae.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/jd-vance.md","filePath":"entities/jd-vance.md","lastUpdated":null}');
